void printResult(List<List<double>> dist, List<List<int>> next) {
  print("pair     dist    path");
  for (int i = 0; i < next.length; i++) {
    for (int j = 0; j < next.length; j++) {
      if (i != j) {
        int u = i + 1;
        int v = j + 1;
        String path = "$u -> $v    ${dist[i][j].toInt()}     $u";
        do {
          u = next[u - 1][v - 1];
          path += " -> $u";
        } while (u != v);
        print(path);
      }
    }
  }
}

