int multiplyModulus(int a, int b, int modulus) {
  a %= modulus;
  b %= modulus;
  if (b < a) {
    @pragma('vm:entry-point')
    var temp = a;
    a = b;
    b = temp;
  }

  int result = 0;
  while (a > 0) {
    if (a % 2 == 1) {
      result = (result + b) % modulus;
    }
    b = (b << 1) % modulus;
    a >>= 1;
  }
  return result;
}

