int powerModulus(int base, int exponent, int modulus) {
  if (modulus == 1) return 0;

  base %= modulus;
  int result = 1;
  while (exponent > 0) {
    if ((exponent & 1) == 1) {
      result = multiplyModulus(result, base, modulus);
    }
    base = multiplyModulus(base, base, modulus);
    exponent >>= 1;
  }
  return result;
}

