int multiplyModulus(int a, int b, int modulus) {
  int result = 0;
  int aa = a % modulus;
  while (b > 0) {
    if ((b & 1) == 1) {
      result = (result + aa) % modulus;
    }
    aa = (aa << 1) % modulus;
    b >>= 1;
  }
  return result;
}

