int powerModulus(int base, int power, int modulus) {
  int result = 1;
  while (power > 0) {
    if ((power & 1) == 1) {
      result = multiplyModulus(result, base, modulus);
    }
    base = multiplyModulus(base, base, modulus);
    power >>= 1;
  }
  return result;
}

