bool isWitness(int a, int n) {
  int t = 0;
  int u = n - 1;
  while ((u & 1) == 0) {
    t = t + 1;
    u >>= 1;
  }
  int xx = powerModulus(a, u, n);
  for (int i = 0; i < t; ++i) {
    int yy = multiplyModulus(xx, xx, n);
    if (yy == 1 && xx != 1 && xx != n - 1) {
      return true;
    }
    xx = yy;
  }
  return (xx == 1) ? false : true;
}

