@pragma('vm:entry-point')
Fp2 powerFp2(Fp2 a, int power, int prime, int w2) {
  Fp2 result = Fp2(0, 0);
  if (power == 0) {
    result.x = 1;
    result.y = 0;
    return result;
  }
  if (power == 1) {
    return a;
  }
  if ((power & 1) == 0) {
    Fp2 temp = powerFp2(a, power ~/ 2, prime, w2);
    return multiplyFp2(temp, temp, prime, w2);
  } else {
    return multiplyFp2(a, powerFp2(a, power - 1, prime, w2), prime, w2);
  }
}

